25	import * as Fragment from 'core/fragment';
26	import * as FormChangeChecker from 'core_form/changechecker';
27	import * as ModalEvents from 'core/modal_events';
28	import * as Notification from 'core/notification';
29	import BankSwitcher from 'core_question/bank_switcher';
30	
31	const SELECTORS = {
32	    ADD_TO_QUIZ_CONTAINER: 'td.addtoquizaction',
33	    ANCHOR: 'a[href]',
34	    PREVIEW_CONTAINER: 'td.previewquestionaction',
35	    ADD_QUESTIONS_FORM: 'form#questionsubmit',
36	    SORTERS: '.sorters',
37	    SWITCH_TO_OTHER_BANK: 'button[data-action="switch-question-bank"]',
38	    NEW_BANKMOD_ID: 'data-newmodid',
39	    BANK_SEARCH: '#searchbanks',
40	    GO_BACK_BUTTON: 'button[data-action="go-back"]',
41	    ADD_ON_PAGE_FORM_ELEMENT: 'input[name="addonpage"]',
42	    CMID_FORM_ELEMENT: 'form#questionsubmit input[name="cmid"]',
43	};
44	
45	export default class ModalQuizQuestionBank extends Modal {
46	    static TYPE = 'mod_quiz-quiz-question-bank';
47	
48	    /**
49	     * Create the question bank modal.
50	     *
51	     * @param {Number} contextId Current module context id.
52	     * @param {Number} bankCmId Current question bank course module id.
53	     * @param {Number} quizCmId Current quiz course module id.
54	     * @param {Number} courseId Current course id, required for switching banks.
55	     */
56	    static init(contextId, bankCmId, quizCmId, courseId) {
57	        const selector = '.menu [data-action="questionbank"]';
58	        document.addEventListener('click', (e) => {
59	            const trigger = e.target.closest(selector);
60	            if (!trigger) {
61	                return;
62	            }
63	            e.preventDefault();
64	
65	            ModalQuizQuestionBank.create({
66	                contextId,
67	                quizCmId,
68	                bankCmId,
69	                title: trigger.dataset.header,
70	                addOnPage: trigger.dataset.addonpage,
71	                templateContext: {
72	                    hidden: true,
73	                },
74	                large: true,
75	                courseId,
76	            });
77	        });
78	    }
79	
80	    /**
81	     * Override the parent show function.
82	     *
83	     * Reload the body contents when the modal is shown. The current
84	     * window URL is used to inform the new content that should be
85	     * displayed.
86	     *
87	     * @method show
88	     * @return {void}
89	     */
90	    show() {
91	        this.reloadBodyContent(window.location.search);
92	        return super.show(this);
93	    }
94	
95	    /**
96	     * Set the modal body to an updated fragment.
97	     *
98	     * @param {string} querystring URL encoded string.
99	     * @param {Number} bankcmid The CMID of the question bank to load.
100	     */
101	    bodyFragment(querystring, bankcmid) {
102	        return Fragment.loadFragment(
103	            'mod_quiz',
104	            'quiz_question_bank',
105	            this.getContextId(),
106	            {
107	                querystring,
108	                quizcmid: this.quizCmId,
109	                bankcmid,
110	            },
111	        );
112	    }
113	
114	    /**
115	     * Replaces the current body contents with a new version of the question
116	     * bank.
117	     *
118	     * The contents of the question bank are generated using the provided
119	     * query string.
120	     *
121	     * @method reloadBodyContent
122	     * @param {string} querystring URL encoded string.
123	     */
124	    reloadBodyContent(querystring) {
125	        // Load the question bank fragment to be displayed in the modal and hide the 'go back' button.
126	        this.hideFooter();
127	        this.setTitle(this.originalTitle);
128	        const lastBankCmid = window.sessionStorage.getItem('lastBankCmid');
129	        let bankCmid = lastBankCmid ? lastBankCmid : this.bankCmId;
130	        const bodyFragment = this.bodyFragment(querystring, bankCmid)
131	            .catch((ex) => {
132	                if (lastBankCmid && (ex.errorcode === 'nopermissions' || ex.errorcode === 'invalidcoursemodule')) {
133	                    // The user has lost access to their last accessed bank, try again with the current bank.
134	                    window.sessionStorage.removeItem('lastBankCmid');
135	                    bankCmid = this.bankCmId;
136	                    return this.bodyFragment(querystring, this.bankCmId);
137	                } else {
138	                    Notification.exception(ex);
139	                    return '';
140	                }
141	            });
142	        this.setBody(bodyFragment);
143	    }
144	
145	    /**
146	     * Update the URL of the anchor element that the user clicked on to make
147	     * sure that the question is added to the correct page.
148	     *
149	     * @method handleAddToQuizEvent
150	     * @param {event} e A JavaScript event
151	     * @param {object} anchorElement The anchor element that was triggered
152	     */
153	    handleAddToQuizEvent(e, anchorElement) {
154	        // If the user clicks the plus icon to add the question to the page
155	        // directly then we need to intercept the click in order to adjust the
156	        // href and include the correct add on page id and cmid before the page is
157	        // redirected.
158	        const href = new URL(anchorElement.getAttribute('href'));
159	        href.searchParams.set('addonpage', this.getAddOnPageId());
160	        href.searchParams.set('cmid', this.quizCmId);
